def solve(I):
    S=frozenset((r,c) for r in range(7) for c in range(7) if I[r][c]==8)
    pieces=[]
    for r in range(6):
        for c in range(6):
            box=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            if all(x in S for x in box): pieces.append((frozenset(box),1))
            for miss,(col) in zip(range(4),[2,4,3,1]):
                L=frozenset(box[i] for i in range(4) if i!=miss)
                if all(x in S for x in L): pieces.append((L,col))
    sols=[]
    def search(rem,acc):
        if not rem: sols.append(dict(acc)); return
        x=min(rem)
        for ps,col in pieces:
            if x in ps and ps<=rem: search(rem-ps,acc+[(cell,col) for cell in ps])
    search(S,[])
    return sols
